 public function testAtomicConsumptionPersistsNonceAndBindingTogether():void{global $wpdb;$auth=hash('sha256','atomic-auth');$nonce='atomic_nonce_12345678901234567890';[$pid,$ph]=$this->package('atomic-package');$saved=DigiForge\POD\ProductionExecutionConsumptionRepository::consume($nonce,$auth,$pid,$ph,get_current_user_id());self::assertFalse(is_wp_error($saved));self::assertSame($auth,$wpdb->get_var($wpdb->prepare('SELECT authorization_hash FROM '.DigiForge\Database\Tables::pod_execution_nonces().' WHERE nonce_hash=%s',hash('sha256',$nonce))));$binding=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DigiForge\Database\Tables::pod_authorization_bindings().' WHERE authorization_hash=%s',$auth),ARRAY_A);self::assertSame($pid,(int)$binding['package_id']);self::assertSame($ph,$binding['package_hash']);$replay=DigiForge\POD\ProductionExecutionConsumptionRepository::consume($nonce,$auth,$pid,$ph,get_current_user_id());self::assertWPError($replay);self::assertSame('digiforge_execution_replay',$replay->get_error_code());}
