 public function testIntegrityDrillDownCorrelatesDurableOutcomeEvidence():void{global $wpdb;$now=current_time('mysql',true);$auth=hash('sha256','integrity-correlation-auth');$out=hash('sha256','integrity-correlation-outcome');$wpdb->insert(DigiForge\Database\Tables::pod_execution_nonces(),['nonce_hash'=>hash('sha256','integrity-correlation-nonce'),'authorization_hash'=>$auth,'consumed_by'=>get_current_user_id(),'consumed_at'=>$now]);$wpdb->insert(DigiForge\Database\Tables::pod_execution_outcomes(),['authorization_hash'=>$auth,'outcome_type'=>'FAILED','outcome_hash'=>$out,'created_at'=>$now]);$x=(new DigiForge\POD\ProductionProvenanceIntegrityReadModel())->recent(200);$match=null;foreach($x['items'] as $item)if($item['authorization_hash']===$auth){$match=$item;break;}self::assertIsArray($match);self::assertSame('LEGACY_UNBOUND',$match['type']);self::assertSame($out,$match['outcome']['outcome_hash']);self::assertMatchesRegularExpression('/^[a-f0-9]{64}$/',$match['correlation_hash']);self::assertFalse($x['retry_permitted']);self::assertFalse($x['external_execution_authorized']);}

