 public function testSchema21HistoricalIntegrityEvidenceSurvivesRepairWithoutReactivation():void{
  global $wpdb;self::assertSame(DigiForge\Database\Tables::pod_provenance_integrity_evidence(),$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',DigiForge\Database\Tables::pod_provenance_integrity_evidence())));
  [$pid,$ph]=$this->package('historical-repair-package');$auth=hash('sha256','historical-repair-auth');$nonce='historical_repair_nonce_1234567890123';$nh=hash('sha256',$nonce);$now=current_time('mysql',true);
  $wpdb->insert(DigiForge\Database\Tables::pod_execution_nonces(),['nonce_hash'=>$nh,'authorization_hash'=>$auth,'consumed_by'=>get_current_user_id(),'consumed_at'=>$now]);
  $wrong=hash('sha256','historical-wrong-package');$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>$pid,'package_hash'=>$wrong,'authorization_hash'=>$auth,'nonce_hash'=>$nh,'bound_by'=>get_current_user_id(),'bound_at'=>$now]);
  $before=(new DigiForge\POD\ProductionProvenanceIntegrityReadModel())->recent(200);$item=null;foreach($before['items'] as $candidate)if(($candidate['authorization_hash']??'')===$auth&&($candidate['type']??'')==='BINDING_PACKAGE_MISMATCH'){$item=$candidate;break;}self::assertIsArray($item);self::assertFalse($item['historical_evidence']);
  $ack=DigiForge\POD\ProductionProvenanceIntegrityAcknowledgementRepository::acknowledge($item['correlation_hash'],$auth,$item['type'],get_current_user_id());self::assertFalse(is_wp_error($ack));self::assertFalse($ack['retry_permitted']);self::assertFalse($ack['external_execution_authorized']);
  $wpdb->update(DigiForge\Database\Tables::pod_authorization_bindings(),['package_hash'=>$ph],['authorization_hash'=>$auth]);
  $after=(new DigiForge\POD\ProductionProvenanceIntegrityReadModel())->recent(200);$historical=null;foreach($after['items'] as $candidate)if(($candidate['correlation_hash']??'')===$item['correlation_hash']){$historical=$candidate;break;}self::assertIsArray($historical);self::assertTrue($historical['historical_evidence']);self::assertSame('ACKNOWLEDGED',$historical['operator_state']);self::assertFalse($historical['retry_permitted']);self::assertFalse($historical['external_execution_authorized']);
  self::assertSame($auth,$wpdb->get_var($wpdb->prepare('SELECT authorization_hash FROM '.DigiForge\Database\Tables::pod_execution_nonces().' WHERE nonce_hash=%s',$nh)));self::assertSame('0',(string)$wpdb->get_var($wpdb->prepare('SELECT external_execution_authorized FROM '.DigiForge\Database\Tables::pod_authorization_packages().' WHERE id=%d',$pid)));
  $replay=DigiForge\POD\ProductionExecutionConsumptionRepository::consume($nonce,$auth,$pid,$ph,get_current_user_id());self::assertWPError($replay);self::assertSame('digiforge_execution_replay',$replay->get_error_code());self::assertFalse($replay->get_error_data()['retry_permitted']);self::assertFalse($replay->get_error_data()['external_execution_authorized']);
 }

 public function testPermitPersistenceReconciliationIsReadOnlyAndNeverRestoresAuthority():void{
  global $wpdb;[$pid,$ph]=$this->package('persistence-reconcile-package');$auth=hash('sha256','persistence-reconcile-auth');$nonce='persistence_reconcile_nonce_123456789';$nh=hash('sha256',$nonce);
  $unknown=(new DigiForge\POD\ProductionPermitPersistenceReadModel())->project($nh,$auth,$pid,$ph);self::assertSame('UNKNOWN',$unknown['persistence_state']);self::assertFalse($unknown['nonce_consumed']);self::assertFalse($unknown['retry_permitted']);self::assertFalse($unknown['external_execution_authorized']);self::assertTrue($unknown['read_only']);
