 }

 public function testPermitPersistenceObservationTransitionsWithoutGrantingRetryOrAuthority():void{
  global $wpdb;[$pid,$ph]=$this->package('persistence-observation-package');$auth=hash('sha256','persistence-observation-auth');$nonce='persistence_observation_nonce_1234567';$nh=hash('sha256',$nonce);
  $unknown=(new DigiForge\POD\ProductionPermitPersistenceReadModel())->project($nh,$auth,$pid,$ph);DigiForge\POD\ProductionPermitPersistenceObservationRepository::observe($nh,$auth,$pid,$ph,$unknown);$s=DigiForge\POD\ProductionPermitPersistenceObservationRepository::summary();self::assertGreaterThanOrEqual(1,$s['unknown_count']);self::assertFalse($s['retry_permitted']);self::assertFalse($s['external_execution_authorized']);
  $saved=DigiForge\POD\ProductionExecutionConsumptionRepository::consume($nonce,$auth,$pid,$ph,get_current_user_id());self::assertFalse(is_wp_error($saved));$observed=(new DigiForge\POD\ProductionPermitPersistenceReadModel())->project($nh,$auth,$pid,$ph);DigiForge\POD\ProductionPermitPersistenceObservationRepository::observe($nh,$auth,$pid,$ph,$observed);
  $row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.DigiForge\Database\Tables::pod_permit_persistence_observations().' WHERE authorization_hash=%s',$auth),ARRAY_A);self::assertSame('PERSISTED_OBSERVED',$row['persistence_state']);self::assertSame('0',(string)$wpdb->get_var($wpdb->prepare('SELECT external_execution_authorized FROM '.DigiForge\Database\Tables::pod_authorization_packages().' WHERE id=%d',$pid)));
  $attention=(new DigiForge\Portal\AttentionReadModel())->summary();self::assertGreaterThanOrEqual(1,$attention['production_permit_persistence_observed']);self::assertSame('READ_ONLY_NO_EXECUTION',$attention['external_execution_state']);
 }
 public function testAttentionSeparatesHistoricalIntegrityFromCurrentOpenAttention():void{
  global $wpdb;[$pid,$ph]=$this->package('attention-history-package');$auth=hash('sha256','attention-history-auth');$now=current_time('mysql',true);$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>$pid,'package_hash'=>hash('sha256','attention-history-wrong'),'authorization_hash'=>$auth,'nonce_hash'=>hash('sha256','attention-history-nonce'),'bound_by'=>get_current_user_id(),'bound_at'=>$now]);
  $first=(new DigiForge\POD\ProductionProvenanceIntegrityReadModel())->recent(200);$match=null;foreach($first['items'] as $candidate)if(($candidate['authorization_hash']??'')===$auth){$match=$candidate;break;}self::assertIsArray($match);$wpdb->update(DigiForge\Database\Tables::pod_authorization_bindings(),['package_hash'=>$ph],['authorization_hash'=>$auth]);
  $attention=(new DigiForge\Portal\AttentionReadModel())->summary();self::assertGreaterThanOrEqual(1,$attention['production_provenance_integrity_historical']);self::assertFalse($attention['production_provenance_integrity_projection']['retry_permitted']);self::assertFalse($attention['production_provenance_integrity_projection']['external_execution_authorized']);
 }

 public function testAcknowledgementInsertRaceAcceptsIdenticalWinnerAndRejectsDivergentWinner():void{
  global $wpdb;$now=current_time('mysql',true);$auth=hash('sha256','ack-race-auth');$wpdb->insert(DigiForge\Database\Tables::pod_execution_nonces(),['nonce_hash'=>hash('sha256','ack-race-nonce'),'authorization_hash'=>$auth,'consumed_by'=>get_current_user_id(),'consumed_at'=>$now]);$x=(new DigiForge\POD\ProductionProvenanceIntegrityReadModel())->recent(200);$item=null;foreach($x['items'] as $candidate)if(($candidate['authorization_hash']??'')===$auth){$item=$candidate;break;}self::assertIsArray($item);$reviewer=get_current_user_id();
  DigiForge\POD\ProductionProvenanceIntegrityAcknowledgementRepository::setBeforeInsertHookForTest(function(array $row)use($wpdb):void{$wpdb->insert(DigiForge\Database\Tables::pod_provenance_integrity_acknowledgements(),$row);});
  $same=DigiForge\POD\ProductionProvenanceIntegrityAcknowledgementRepository::acknowledge($item['correlation_hash'],$auth,$item['type'],$reviewer);self::assertFalse(is_wp_error($same));self::assertFalse($same['retry_permitted']);self::assertFalse($same['external_execution_authorized']);
  $auth2=hash('sha256','ack-race-conflict-auth');$wpdb->insert(DigiForge\Database\Tables::pod_execution_nonces(),['nonce_hash'=>hash('sha256','ack-race-conflict-nonce'),'authorization_hash'=>$auth2,'consumed_by'=>$reviewer,'consumed_at'=>$now]);$y=(new DigiForge\POD\ProductionProvenanceIntegrityReadModel())->recent(200);$item2=null;foreach($y['items'] as $candidate)if(($candidate['authorization_hash']??'')===$auth2){$item2=$candidate;break;}self::assertIsArray($item2);
  DigiForge\POD\ProductionProvenanceIntegrityAcknowledgementRepository::setBeforeInsertHookForTest(function(array $row)use($wpdb):void{$row['reviewed_by']=(int)$row['reviewed_by']+1000;$row['acknowledgement_hash']=hash('sha256','divergent-race-winner');$wpdb->insert(DigiForge\Database\Tables::pod_provenance_integrity_acknowledgements(),$row);});
  $different=DigiForge\POD\ProductionProvenanceIntegrityAcknowledgementRepository::acknowledge($item2['correlation_hash'],$auth2,$item2['type'],$reviewer);self::assertWPError($different);self::assertSame('production_integrity_ack_conflict',$different->get_error_code());
 }
 public function testPersistenceDrilldownIsBoundedReadOnlyAndNonAuthorizing():void{
  global $wpdb;[$pid,$ph]=$this->package('drilldown-package');$auth=hash('sha256','drilldown-auth');$nh=hash('sha256','drilldown-nonce');$projection=(new DigiForge\POD\ProductionPermitPersistenceReadModel())->project($nh,$auth,$pid,$ph);DigiForge\POD\ProductionPermitPersistenceObservationRepository::observe($nh,$auth,$pid,$ph,$projection);$x=DigiForge\POD\ProductionPermitPersistenceObservationRepository::recent(500);self::assertLessThanOrEqual(200,$x['count']);self::assertTrue($x['read_only']);self::assertFalse($x['retry_permitted']);self::assertFalse($x['external_execution_authorized']);foreach($x['items'] as $item){self::assertContains($item['persistence_state'],['UNKNOWN','PERSISTED_OBSERVED']);self::assertFalse($item['retry_permitted']);self::assertFalse($item['external_execution_authorized']);}
 }
